import { formatZar } from "./money.ts";

/**
 * Strip internal-only framing from a stored document before it is shown to a
 * customer. The banner is generated by `buildQuoteDocument`, but stripping is
 * deliberately position-independent and repeated so a document assembled some
 * other way cannot leak internal text onto a customer-facing page.
 */
export function customerQuoteText(summary: string): string {
  return summary
    .replace(/INTERNAL QUOTE DRAFT\.\s*This has not been sent\./gi, "")
    .replace(/\s*INTERNAL[^\n]*/gi, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

export type InvoiceFigure =
  | {
      ok: true;
      cents: number;
      netCents: number;
      vatCents: number;
      treatment: VatTreatment;
      memo: string;
    }
  | { ok: false; error: string };

/**
 * `valueCents` is the approved quote figure. `cents` in the result is what the customer owes:
 * - none (default): nothing added, VAT not stated
 * - standard: quote figure is net, 15% VAT is added
 * - included: quote figure already contains VAT
 * - zero_rated: quote figure is net, VAT is 0%
 */
export function quoteInvoice(valueCents: number, treatment: VatTreatment = "none"): InvoiceFigure {
  if (!Number.isInteger(valueCents) || valueCents <= 0) {
    return { ok: false, error: "There is no approved figure to invoice." };
  }
  const split = vatBreakdown(valueCents, treatment);
  if (!split.ok) return split;
  const memo =
    treatment === "none"
      ? "Labour from the approved quote. VAT was not stated, so none is added. The invoice has not been emailed."
      : `Labour from the approved quote. ${VAT_TREATMENT_LABELS[treatment]}. The invoice has not been emailed.`;
  return {
    ok: true,
    cents: split.grossCents,
    netCents: split.netCents,
    vatCents: split.vatCents,
    treatment,
    memo,
  };
}

export function receiptForInvoice(
  amountCents: number,
): { ok: true; cents: number; memo: string } | { ok: false; error: string } {
  if (!Number.isInteger(amountCents) || amountCents <= 0) {
    return { ok: false, error: "There is no invoice figure to receive." };
  }
  return {
    ok: true,
    cents: amountCents,
    memo: "Founder recorded that this invoice was paid in full. The customer was not emailed.",
  };
}

/**
 * The customer-facing reference for a document, and the payment reference the
 * customer quotes back to us.
 *
 * 8 hex characters is 32 bits — birthday collisions land around 77k documents,
 * which is inside this office's lifetime. Use 12 hex characters (48 bits,
 * effectively collision-free) and keep it readable enough to transcribe.
 */
export function documentRef(id: string): string {
  const compact = id.replace(/-/g, "").toUpperCase();
  // Crockford-ish alphabet: no I, L, O, U — these get read over the phone.
  const alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
  let numeric = 0n;
  for (const char of compact) {
    const value = BigInt(parseInt(char, 16) || 0);
    numeric = ((numeric << 8n) | value) & 0xffffffffffffn;
  }
  let out = "";
  let remaining = numeric;
  for (let i = 0; i < 10; i += 1) {
    out = alphabet[Number(remaining % 32n)] + out;
    remaining >>= 5n;
  }
  return `VA-${out}`;
}

export type PaymentEnv = Record<string, string | undefined>;
export type PaymentMethod = {
  id: "eft" | "wire" | "card";
  title: string;
  available: boolean;
  detail: string;
};

type BankDetails = {
  bank: string;
  account: string;
  branch: string;
  beneficiary: string;
  swift: string;
};

/** Bank details come from the server environment, never from source code. Null when incomplete. */
export function bankDetails(env: PaymentEnv): BankDetails | null {
  const pick = (key: string) => (env[key] ?? "").replace(/\s+/g, " ").trim().slice(0, 80);
  const bank = pick("PAYMENT_BANK_NAME");
  const account = pick("PAYMENT_ACCOUNT_NUMBER");
  const branch = pick("PAYMENT_BRANCH_CODE");
  const beneficiary = pick("PAYMENT_BENEFICIARY");
  if (!bank || !account || !branch || !beneficiary) return null;
  return { bank, account, branch, beneficiary, swift: pick("PAYMENT_SWIFT") };
}

const NO_BANK_DETAIL = "Bank details are sent with your quote or invoice.";

export function paymentMethods(env: PaymentEnv): PaymentMethod[] {
  const bank = bankDetails(env);
  const methods: PaymentMethod[] = [
    {
      id: "eft",
      title: "EFT",
      available: true,
      detail: bank
        ? `${bank.bank}. Account ${bank.account}. Branch ${bank.branch}. Beneficiary ${bank.beneficiary}.`
        : NO_BANK_DETAIL,
    },
    {
      id: "wire",
      title: "International wire",
      available: true,
      detail:
        bank && bank.swift
          ? `SWIFT ${bank.swift}. ${bank.bank}. Account ${bank.account}. Branch ${bank.branch}.`
          : NO_BANK_DETAIL,
    },
    {
      id: "card",
      title: "Card",
      available: false,
      detail: "Card checkout is not connected. Do not send card numbers by email.",
    },
  ];
  return methods;
}

/**
 * True while every available method is still pointing the payer at the
 * "details are sent with your quote" sentinel — i.e. no bank details are
 * configured yet, so the payment form should say so up front.
 *
 * Only *available* methods count. The unavailable card method never carries
 * bank details, so including it made this permanently false and the notice
 * never rendered even with no bank details configured.
 */
export function allMethodsAwaitBankDetails(methods: PaymentMethod[]): boolean {
  const available = methods.filter((method) => method.available);
  return available.length > 0 && available.every((method) => method.detail === NO_BANK_DETAIL);
}

export function paymentInstructionsText(env: PaymentEnv): string {
  const bank = bankDetails(env);
  if (!bank) {
    return [
      "Bank details are sent with the quote or invoice.",
      "Reference: the quote or invoice reference.",
      "Card payment is not available.",
    ].join(" ");
  }
  return [
    `EFT: ${bank.bank}, account ${bank.account}, branch ${bank.branch}, beneficiary ${bank.beneficiary}.`,
    bank.swift ? `International wire: SWIFT ${bank.swift}, ${bank.bank}, same account.` : "",
    "Reference: the quote or invoice reference.",
    "Card payment is not available.",
  ]
    .filter(Boolean)
    .join(" ");
}

export type VatSummary = { treatment: VatTreatment; netCents: number; vatCents: number };

function vatLines(vat: VatSummary | undefined): string[] {
  if (!vat || vat.treatment === "none") return ["VAT was not stated, so none is added."];
  if (vat.treatment === "zero_rated")
    return [`Excluding VAT: ${formatZar(vat.netCents)}.`, "VAT at 0% (zero-rated)."];
  return [`Excluding VAT: ${formatZar(vat.netCents)}.`, `VAT at 15%: ${formatZar(vat.vatCents)}.`];
}

export function invoiceCopy(
  companyName: string,
  cents: number,
  reference?: string,
  vat?: VatSummary,
): string {
  const name = companyName.trim() || "Customer";
  return [
    `Invoice for ${name}.`,
    "Labour from the accepted quote.",
    ...vatLines(vat),
    `Amount due ${formatZar(cents)}.`,
    reference ? `Reference: ${reference}.` : "",
  ]
    .filter(Boolean)
    .join(" ");
}

export function receiptCopy(companyName: string, cents: number, vat?: VatSummary): string {
  const name = companyName.trim() || "Customer";
  return [
    `Receipt for ${name}.`,
    `Amount received ${formatZar(cents)}.`,
    "This matches the invoice.",
    ...vatLines(vat),
  ].join(" ");
}

export function paymentNote(value: string): string {
  return value.trim().replace(/\s+/g, " ").slice(0, 400);
}

export function withPaymentNote(body: string, note: string): string {
  const extra = paymentNote(note);
  if (!extra) return body;
  return `${body} Pay: ${extra}`;
}

export function deliveryJob(
  companyName: string,
  quoteSummary: string,
): { title: string; summary: string } {
  const name = companyName.trim() || "Customer";
  const scope = customerQuoteText(quoteSummary);
  return {
    title: `Deliver · ${name}`,
    summary: scope || "Accepted quote. Scope is the approved labour only.",
  };
}

export type VatTreatment = "none" | "standard" | "included" | "zero_rated";

export const VAT_RATE_BPS = 1500; // South Africa standard rate, 15.00%

/**
 * Integer-cent VAT breakdown. `cents` is the figure on the quote:
 * - none: VAT not stated, nothing added (current default behaviour)
 * - standard: cents is the net amount, 15% is added
 * - included: cents already contains VAT, so net and VAT are extracted
 * - zero_rated: cents is the net amount and VAT is 0% (for example qualifying exports)
 * Whether a treatment applies to a customer is the founder's call; this only does the arithmetic.
 */
export function vatBreakdown(
  cents: number,
  treatment: VatTreatment,
):
  | { ok: true; netCents: number; vatCents: number; grossCents: number }
  | { ok: false; error: string } {
  if (!Number.isInteger(cents) || cents <= 0)
    return { ok: false, error: "There is no figure to apply VAT to." };
  switch (treatment) {
    case "none":
    case "zero_rated":
      return { ok: true, netCents: cents, vatCents: 0, grossCents: cents };
    case "standard": {
      const vat = Math.floor((cents * VAT_RATE_BPS + 5000) / 10000);
      return { ok: true, netCents: cents, vatCents: vat, grossCents: cents + vat };
    }
    case "included": {
      const net = Math.floor((cents * 10000 + (10000 + VAT_RATE_BPS) / 2) / (10000 + VAT_RATE_BPS));
      return { ok: true, netCents: net, vatCents: cents - net, grossCents: cents };
    }
    default:
      return { ok: false, error: "Unknown VAT treatment." };
  }
}

/**
 * Maps the `vatTreatment` on an invoice action to integer-cent VAT.
 * Missing treatment keeps the previous behaviour (15% on top). "unstated" and
 * "none" add nothing. An unrecognised value adds nothing rather than inventing VAT.
 */
export function ledgerVat(
  treatment: unknown,
  cents: number,
): { treatment: VatTreatment; vatCents: number; netCents: number } {
  const known: VatTreatment[] = ["none", "standard", "included", "zero_rated"];
  const t: VatTreatment =
    treatment === undefined || treatment === null
      ? "standard"
      : treatment === "unstated"
        ? "none"
        : known.includes(treatment as VatTreatment)
          ? (treatment as VatTreatment)
          : "none";
  const r = vatBreakdown(cents, t);
  if (!r.ok)
    return {
      treatment: "none",
      vatCents: 0,
      netCents: Math.max(0, Number.isInteger(cents) ? cents : 0),
    };
  return { treatment: t, vatCents: r.vatCents, netCents: r.netCents };
}

export const VAT_TREATMENT_LABELS: Record<VatTreatment, string> = {
  none: "No VAT added",
  standard: "Add 15% VAT to the quote figure",
  included: "Quote figure already includes 15% VAT",
  zero_rated: "Zero-rated (0% VAT)",
};

/** Untrusted input to a treatment. Anything unrecognised becomes "none" so VAT is never invented. */
export function parseVatTreatment(value: unknown): VatTreatment {
  return value === "standard" || value === "included" || value === "zero_rated" ? value : "none";
}

/**
 * VAT on money Vantage-ARS PAYS (expenses, campaign spend). `paidCents` is what left the bank.
 * Input VAT is only claimed when the founder says the amount includes it ("included");
 * anything else records no VAT, because a claim needs a valid supplier tax invoice.
 */
export function expenseVat(treatment: unknown, paidCents: number): number {
  if (treatment !== "included") return 0;
  const r = vatBreakdown(paidCents, "included");
  return r.ok ? r.vatCents : 0;
}
